const items = $input.all();
const item = items[0];
if (!item.binary || !item.binary.data) throw new Error('KHONG co binary tu node Tai anh ve tinh');
const bd = item.binary.data;
const s = $('Chuẩn hóa dữ liệu').first().json;
let base64 = bd.data;
if (base64 === 'filesystem-v2' || !base64 || base64.length < 100) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  base64 = buffer.toString('base64');
}
return [{json:{lat:s.lat,lng:s.lng,field_name:s.field_name,field_id:s.field_id,image_base64:base64,mime_type:bd.mimeType||'image/jpeg'}}];

